(function(){window.RoundedPieBridge={update:()=>{},data:()=>window.YunchengCharts?.slices||[],unit:()=>{const amount=document.querySelector('[data-measure="amount"]')?.classList.contains('selected');return amount?(document.querySelector('#opportunity-basis')?.value==='annual'?'万元/年':'万元'):'个项目'},open:i=>document.querySelector('[data-legend-slice="'+i+'"]')?.click()};const previous=render;render=function(){previous();window.RoundedPieBridge.update()};document.body.classList.add('rounded-pie-preview')})();
